import numpy as np
from scipy.optimize import minimize

N = 26

def construct_packing() -> tuple:
    try:
        base_centers = np.loadtxt('storage/episteme/base_416_centers.txt')
        base_radii = np.loadtxt('storage/episteme/base_416_radii.txt')
    except Exception:
        return np.random.rand(N, 2), np.full(N, 0.05)

    # --- Penalized Objective and Constraint Functions (Faithful Replication of Archive #20) ---
    ENCOURAGE_PAIRS = [(2, 3)]
    DISCOURAGE_PAIRS = [] # Original paper did not discourage in the breakthrough run

    ALPHA_ENCOURAGE = 1e2
    BETA_DISCOURAGE = 1e1 # Included for completeness, though not used here
    EPS_CLOSE = 0.005
    EPS_FAR = 0.01

    def cr_to_z(c, r): return np.concatenate([c.flatten(), r])
    def z_to_cr(z): return z[:N*2].reshape(N, 2), z[N*2:]

    def objective_penalized(z):
        centers, radii = z_to_cr(z)
        base_objective = -np.sum(radii)

        encouragement_penalty = 0
        for i, j in ENCOURAGE_PAIRS:
            dist = np.linalg.norm(centers[i] - centers[j])
            encouragement_penalty += np.maximum(0, dist - (radii[i] + radii[j] + EPS_CLOSE))**2

        discouragement_penalty = 0
        for k, l in DISCOURAGE_PAIRS:
            dist = np.linalg.norm(centers[k] - centers[l])
            discouragement_penalty += np.maximum(0, (radii[k] + radii[l] + EPS_FAR) - dist)**2

        return base_objective + (ALPHA_ENCOURAGE * encouragement_penalty) + (BETA_DISCOURAGE * discouragement_penalty)

    def ineq_boundary(z):
        c, r = z_to_cr(z)
        return np.concatenate([c[:,0] - r, 1 - (c[:,0] + r), c[:,1] - r, 1 - (c[:,1] + r)])

    def ineq_nonoverlap(z):
        c, r = z_to_cr(z)
        diff = c[:, None, :] - c[None, :, :]; dist = np.sqrt(np.sum(diff**2, axis=-1))
        iu = np.triu_indices(N, 1)
        return dist[iu] - (r[iu[0]] + r[iu[1]])

    def _ensure_validity(c, r):
        for _ in range(10):
            v=0
            for i in range(N):
                for j in range(i + 1, N):
                    dist = np.linalg.norm(c[i] - c[j]); rad_sum = r[i] + r[j]
                    if dist < rad_sum: v+=1; scale = (dist/rad_sum)*(1.0-1e-9); r[i]*=scale; r[j]*=scale
            if v==0: break
        r_vec = r.reshape(-1, 1); c = np.clip(c, r_vec, 1.0 - r_vec)
        return c, np.maximum(r, 1e-6)

    # --- Multi-Start Jittered Refinement ---
    best_score = -np.inf; best_packing = (None, None)
    jitter_amplitudes = [1.0e-3, 2.0e-3, 3.0e-3, 4.0e-3, 5.0e-3]
    restarts_per_amplitude = 3

    for amp in jitter_amplitudes:
        for i in range(restarts_per_amplitude):
            np.random.seed(int(amp*1e6) + i)
            jitter = np.random.uniform(-amp, amp, size=base_centers.shape)
            initial_centers = np.clip(base_centers + jitter, 1e-6, 1 - 1e-6)

            initial_z = cr_to_z(initial_centers, base_radii)
            bounds = [(0,1)]*N*2 + [(1e-6, 0.5)]*N
            constraints = [{'type': 'ineq', 'fun': ineq_boundary}, {'type': 'ineq', 'fun': ineq_nonoverlap}]

            res = minimize(objective_penalized, initial_z, method='SLSQP', bounds=bounds, constraints=constraints, options={'maxiter': 500, 'ftol': 1e-9})

            if res.success:
                c_res, r_res = z_to_cr(res.x)
                c_final, r_final = _ensure_validity(c_res, r_res)
                current_score = np.sum(r_final)
                if current_score > best_score:
                    best_score = current_score
                    best_packing = (c_final, r_final)

    if best_packing[0] is None:
        return _ensure_validity(base_centers, base_radii)

    return best_packing
